  1	<!DOCTYPE html>
  2	<html lang="en">
  3	<head>
  4	<meta charset="utf-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1">
  6	<title>Tetris</title>
  7	<style>
  8	  :root {
  9	    --cell: 28px;
 10	    --bg: #14161c;
 11	    --panel: #1e2129;
 12	    --line: #2a2e38;
 13	    --text: #e8eaf0;
 14	    --muted: #9aa0ad;
 15	  }
 16	  * { box-sizing: border-box; }
 17	  body {
 18	    margin: 0;
 19	    min-height: 100vh;
 20	    display: flex;
 21	    align-items: center;
 22	    justify-content: center;
 23	    background: var(--bg);
 24	    color: var(--text);
 25	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
 26	  }
 27	  .game {
 28	    display: flex;
 29	    gap: 20px;
 30	    align-items: flex-start;
 31	    padding: 20px;
 32	  }
 33	  .board-wrap { position: relative; }
 34	  .board {
 35	    display: grid;
 36	    grid-template-columns: repeat(10, var(--cell));
 37	    grid-template-rows: repeat(20, var(--cell));
 38	    gap: 1px;
 39	    padding: 1px;
 40	    background: var(--line);
 41	    border: 2px solid var(--line);
 42	  }
 43	  .cell { background: var(--panel); }
 44	  .cell[data-filled="true"] { box-shadow: inset 0 0 0 2px rgba(255,255,255,0.18); }
 45	  .overlay {
 46	    position: absolute;
 47	    inset: 0;
 48	    display: flex;
 49	    align-items: center;
 50	    justify-content: center;
 51	    background: rgba(0,0,0,0.6);
 52	    font-size: 24px;
 53	    font-weight: 600;
 54	  }
 55	  .side {
 56	    display: flex;
 57	    flex-direction: column;
 58	    gap: 14px;
 59	    min-width: 140px;
 60	  }
 61	  .box {
 62	    background: var(--panel);
 63	    border: 1px solid var(--line);
 64	    padding: 10px 12px;
 65	  }
 66	  .label {
 67	    font-size: 11px;
 68	    text-transform: uppercase;
 69	    letter-spacing: 0.08em;
 70	    color: var(--muted);
 71	  }
 72	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
 73	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
 74	  .mini {
 75	    display: grid;
 76	    grid-template-columns: repeat(4, 16px);
 77	    grid-template-rows: repeat(2, 16px);
 78	    gap: 1px;
 79	  }
 80	  .mini-cell { background: transparent; }
 81	  .hold { margin-top: 8px; min-height: 33px; }
 82	  button {
 83	    font: inherit;
 84	    color: var(--text);
 85	    background: var(--panel);
 86	    border: 1px solid var(--line);
 87	    padding: 8px 12px;
 88	    cursor: pointer;
 89	  }
 90	  button:hover { border-color: var(--muted); }
 91	  .help { font-size: 12px; color: var(--muted); line-height: 1.6; }
 92	  .p-I { background: #22c7e0; }
 93	  .p-O { background: #f2c511; }
 94	  .p-T { background: #9b4dca; }
 95	  .p-S { background: #3cb44b; }
 96	  .p-Z { background: #e6194b; }
 97	  .p-J { background: #2f6fdf; }
 98	  .p-L { background: #f58231; }
 99	</style>
100	</head>
101	<body>
102	<div class="game">
103	  <div class="board-wrap">
104	    <div class="board" data-testid="board" id="board"></div>
105	  </div>
106	  <div class="side">
107	    <div class="box">
108	      <div class="label">Score</div>
109	      <div class="value" data-testid="score" id="score">0</div>
110	    </div>
111	    <div class="box">
112	      <div class="label">Level</div>
113	      <div class="value" data-testid="level" id="level">1</div>
114	    </div>
115	    <div class="box">
116	      <div class="label">Lines</div>
117	      <div class="value" data-testid="lines" id="lines">0</div>
118	    </div>
119	    <div class="box">
120	      <div class="label">Hold</div>
121	      <div class="hold" data-testid="hold-piece" data-piece="" id="hold"></div>
122	    </div>
123	    <div class="box">
124	      <div class="label">Next</div>
125	      <div class="next-list" data-testid="next-piece" id="next"></div>
126	    </div>
127	    <button type="button" id="new-game">New game</button>
128	    <div class="help">
129	      ← → move<br>
130	      ↓ soft drop<br>
131	      Space hard drop<br>
132	      ↑ rotate<br>
133	      C hold
134	    </div>
135	  </div>
136	</div>
137	
138	<script>
139	(function () {
140	  "use strict";
141	
142	  var ROWS = 20;
143	  var COLS = 10;
144	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
145	  var PREVIEW = 1;
146	  var LINES_PER_LEVEL = 10;
147	  var LOCK_DELAY_TICKS = 2;   // gravity steps a piece may spend unable to fall
148	  var MAX_LOCK_RESETS = 3;    // times per piece a sideways move or soft drop restarts the delay
149	
150	  // Points for rows cleared at once, times the level. Clearing rows together
151	  // must always beat clearing the same rows one at a time.
152	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
153	  var SOFT_DROP_POINTS = 1;   // per cell moved down by soft drop
154	  var HARD_DROP_POINTS = 2;   // per cell dropped by hard drop
155	
156	  // Each shape is a square matrix; spawn puts its filled cells in rows 0-1.
157	  var SHAPES = {
158	    I: { m: ["....", "IIII", "....", "...."], row: -1, col: 3 },
159	    O: { m: ["OO", "OO"], row: 0, col: 4 },
160	    T: { m: [".T.", "TTT", "..."], row: 0, col: 3 },
161	    S: { m: [".SS", "SS.", "..."], row: 0, col: 3 },
162	    Z: { m: ["ZZ.", ".ZZ", "..."], row: 0, col: 3 },
163	    J: { m: ["J..", "JJJ", "..."], row: 0, col: 3 },
164	    L: { m: ["..L", "LLL", "..."], row: 0, col: 3 }
165	  };
166	
167	  // ---- State ----
168	  var board;        // board[row][col] = "" or piece letter
169	  var current;      // { type, matrix, row, col, lockTicks, lockResets } or null
170	  var held;         // letter in the hold slot, or null
171	  var holdUsed;     // true after a hold, until the next piece locks
172	  var next;         // upcoming piece letters, soonest first
173	  var scripted;     // true while `next` comes from a test-supplied queue
174	  var bag = [];
175	  var score, level, lines, status;
176	  var timer = null;
177	  var timerInterval = 0;
178	
179	  function emptyBoard() {
180	    var b = [];
181	    for (var r = 0; r < ROWS; r++) {
182	      var row = [];
183	      for (var c = 0; c < COLS; c++) row.push("");
184	      b.push(row);
185	    }
186	    return b;
187	  }
188	
189	  function randomType() {
190	    if (bag.length === 0) {
191	      bag = TYPES.slice();
192	      for (var i = bag.length - 1; i > 0; i--) {
193	        var j = Math.floor(Math.random() * (i + 1));
194	        var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
195	      }
196	    }
197	    return bag.pop();
198	  }
199	
200	  function fillPreview() {
201	    if (scripted) return;
202	    while (next.length < PREVIEW) next.push(randomType());
203	  }
204	
205	  function shapeCells(matrix, row, col) {
206	    var cells = [];
207	    for (var r = 0; r < matrix.length; r++) {
208	      for (var c = 0; c < matrix[r].length; c++) {
209	        if (matrix[r][c] !== ".") cells.push([row + r, col + c]);
210	      }
211	    }
212	    return cells;
213	  }
214	
215	  function fits(matrix, row, col) {
216	    var cells = shapeCells(matrix, row, col);
217	    for (var i = 0; i < cells.length; i++) {
218	      var r = cells[i][0], c = cells[i][1];
219	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
220	      if (board[r][c] !== "") return false;
221	    }
222	    return true;
223	  }
224	
225	  // Milliseconds between gravity steps at the current level.
226	  function dropInterval() {
227	    return Math.max(100, 1000 - (level - 1) * 100);
228	  }
229	
230	  function spawn() {
231	    if (next.length === 0) scripted = false;
232	    fillPreview();
233	    var type = next.shift();
234	    fillPreview();
235	    enter(type);
236	  }
237	
238	  // Puts a piece of the given type at the spawn position, or ends the game.
239	  function enter(type) {
240	    var s = SHAPES[type];
241	    var piece = {
242	      type: type, matrix: s.m.slice(), row: s.row, col: s.col,
243	      lockTicks: 0,   // consecutive gravity steps spent unable to fall
244	      lockResets: 0   // lifetime count of lock-delay restarts
245	    };
246	    if (!fits(piece.matrix, piece.row, piece.col)) {
247	      current = null;
248	      status = "gameover";
249	      stopTimer();
250	      return;
251	    }
252	    current = piece;
253	  }
254	
255	  function lock() {
256	    var cells = shapeCells(current.matrix, current.row, current.col);
257	    for (var i = 0; i < cells.length; i++) {
258	      board[cells[i][0]][cells[i][1]] = current.type;
259	    }
260	    current = null;
261	    holdUsed = false;
262	    clearLines();
263	    spawn();
264	  }
265	
266	  // Sets the falling piece aside. The first hold brings in the next piece;
267	  // later holds swap with the held one. Once per piece until it locks.
268	  function hold() {
269	    if (!current || holdUsed) return;
270	    var type = current.type;
271	    current = null;
272	    holdUsed = true;
273	    if (held === null) {
274	      held = type;
275	      spawn();
276	    } else {
277	      var out = held;
278	      held = type;
279	      enter(out);
280	    }
281	  }
282	
283	  // Removes every full row; rows above drop down.
284	  function clearLines() {
285	    var kept = board.filter(function (row) {
286	      return row.some(function (v) { return v === ""; });
287	    });
288	    var cleared = ROWS - kept.length;
289	    if (cleared === 0) return;
290	    while (kept.length < ROWS) kept.unshift(emptyBoard()[0]);
291	    board = kept;
292	    // Points use the level the clear was made at.
293	    score += CLEAR_POINTS[Math.min(cleared, 4)] * level;
294	    var levelsGained = Math.floor((lines + cleared) / LINES_PER_LEVEL) -
295	      Math.floor(lines / LINES_PER_LEVEL);
296	    lines += cleared;
297	    if (levelsGained > 0) setLevelValue(level + levelsGained);
298	  }
299	
300	  // Changes the level and keeps the gravity timer in step with it.
301	  function setLevelValue(n) {
302	    level = n;
303	    if (timer !== null && timerInterval !== dropInterval()) startTimer();
304	  }
305	
306	  function tryMove(dr, dc) {
307	    if (!current) return false;
308	    if (!fits(current.matrix, current.row + dr, current.col + dc)) return false;
309	    current.row += dr;
310	    current.col += dc;
311	    return true;
312	  }
313	
314	  // The single gravity step, used by the real timer and tick().
315	  // A step that cannot move the piece down counts one tick of lock delay.
316	  // Returns true if the piece moved down.
317	  function gravityStep() {
318	    if (status !== "running" || !current) return false;
319	    if (tryMove(1, 0)) {
320	      current.lockTicks = 0;
321	      return true;
322	    }
323	    current.lockTicks++;
324	    if (current.lockTicks >= LOCK_DELAY_TICKS) lock();
325	    return false;
326	  }
327	
328	  // Restarts a running lock delay, up to MAX_LOCK_RESETS times per piece.
329	  function restartLockDelay() {
330	    if (current.lockTicks > 0 && current.lockResets < MAX_LOCK_RESETS) {
331	      current.lockResets++;
332	      current.lockTicks = 0;
333	    }
334	  }
335	
336	  // Soft drop. If the piece cannot fall, it counts like a sideways move:
337	  // it restarts a running lock delay and never adds a lock tick itself.
338	  function softDrop() {
339	    if (tryMove(1, 0)) {
340	      current.lockTicks = 0;
341	      score += SOFT_DROP_POINTS;
342	    } else {
343	      restartLockDelay();
344	    }
345	  }
346	
347	  // Left/right. A move made while the lock delay is running restarts it.
348	  function shift(dc) {
349	    if (tryMove(0, dc)) restartLockDelay();
350	  }
351	
352	  // Clockwise rotation. Tries the rotated shape in place, then shifted
353	  // sideways; if none fit, the piece is left unchanged.
354	  function rotateCW() {
355	    if (!current) return;
356	    var m = current.matrix;
357	    var n = m.length;
358	    var rotated = [];
359	    for (var r = 0; r < n; r++) {
360	      var line = "";
361	      for (var c = 0; c < n; c++) line += m[n - 1 - c][r];
362	      rotated.push(line);
363	    }
364	    var kicks = [0, -1, 1, -2, 2];
365	    for (var i = 0; i < kicks.length; i++) {
366	      var nc = current.col + kicks[i];
367	      if (fits(rotated, current.row, nc)) {
368	        current.matrix = rotated;
369	        current.col = nc;
370	        return;
371	      }
372	    }
373	  }
374	
375	  // Hard drop skips the lock delay.
376	  function hardDrop() {
377	    if (!current) return;
378	    while (tryMove(1, 0)) score += HARD_DROP_POINTS;
379	    lock();
380	  }
381	
382	  function applyInput(action) {
383	    if (status !== "running" || !current) return;
384	    switch (action) {
385	      case "left": shift(-1); break;
386	      case "right": shift(1); break;
387	      case "softDrop": softDrop(); break;
388	      case "hardDrop": hardDrop(); break;
389	      case "rotateCW":
390	      case "rotate": rotateCW(); break;
391	      case "hold": hold(); break;
392	    }
393	  }
394	
395	  // ---- Timer ----
396	  function stopTimer() {
397	    if (timer !== null) { clearInterval(timer); timer = null; }
398	  }
399	
400	  function startTimer() {
401	    stopTimer();
402	    timerInterval = dropInterval();
403	    timer = setInterval(function () {
404	      gravityStep();
405	      render();
406	    }, timerInterval);
407	  }
408	
409	  // ---- Rendering (synchronous) ----
410	  var boardEl = document.getElementById("board");
411	  var nextEl = document.getElementById("next");
412	  var holdEl = document.getElementById("hold");
413	  var boardWrapEl = boardEl.parentNode;
414	  var overlayEl = document.createElement("div");
415	  overlayEl.className = "overlay";
416	  overlayEl.setAttribute("data-testid", "game-over");
417	  overlayEl.textContent = "Game over";
418	  var scoreEl = document.getElementById("score");
419	  var levelEl = document.getElementById("level");
420	  var linesEl = document.getElementById("lines");
421	  var cellEls = [];
422	
423	  (function buildBoard() {
424	    for (var r = 0; r < ROWS; r++) {
425	      cellEls.push([]);
426	      for (var c = 0; c < COLS; c++) {
427	        var el = document.createElement("div");
428	        el.className = "cell";
429	        el.setAttribute("data-testid", "cell");
430	        el.setAttribute("data-row", String(r));
431	        el.setAttribute("data-col", String(c));
432	        el.setAttribute("data-filled", "false");
433	        el.setAttribute("data-piece", "");
434	        boardEl.appendChild(el);
435	        cellEls[r].push(el);
436	      }
437	    }
438	  })();
439	
440	  function paintCell(el, piece) {
441	    el.className = piece ? "cell p-" + piece : "cell";
442	    el.setAttribute("data-filled", piece ? "true" : "false");
443	    el.setAttribute("data-piece", piece);
444	  }
445	
446	  // A 4x2 picture of a piece in its spawn orientation.
447	  function miniPiece(type) {
448	    var m = SHAPES[type].m;
449	    var offset = type === "I" ? 1 : 0; // I's filled row is row 1 of its matrix
450	    var mini = document.createElement("div");
451	    mini.className = "mini";
452	    for (var r = 0; r < 2; r++) {
453	      for (var c = 0; c < 4; c++) {
454	        var ch = m[r + offset] && m[r + offset][c];
455	        var cell = document.createElement("div");
456	        cell.className = ch && ch !== "." ? "mini-cell p-" + type : "mini-cell";
457	        mini.appendChild(cell);
458	      }
459	    }
460	    return mini;
461	  }
462	
463	  function renderNext() {
464	    nextEl.textContent = "";
465	    for (var i = 0; i < Math.min(next.length, PREVIEW); i++) {
466	      var mini = miniPiece(next[i]);
467	      mini.setAttribute("data-testid", "next-piece-item");
468	      mini.setAttribute("data-piece", next[i]);
469	      nextEl.appendChild(mini);
470	    }
471	  }
472	
473	  function renderHold() {
474	    if (holdEl.getAttribute("data-piece") === (held || "")) return;
475	    holdEl.textContent = "";
476	    holdEl.setAttribute("data-piece", held || "");
477	    if (held) holdEl.appendChild(miniPiece(held));
478	  }
479	
480	  function render() {
481	    var view = board.map(function (row) { return row.slice(); });
482	    if (current) {
483	      var cells = shapeCells(current.matrix, current.row, current.col);
484	      for (var i = 0; i < cells.length; i++) {
485	        view[cells[i][0]][cells[i][1]] = current.type;
486	      }
487	    }
488	    for (var r = 0; r < ROWS; r++) {
489	      for (var c = 0; c < COLS; c++) paintCell(cellEls[r][c], view[r][c]);
490	    }
491	    scoreEl.textContent = String(score);
492	    levelEl.textContent = String(level);
493	    linesEl.textContent = String(lines);
494	    // The overlay is in the DOM only while the game is over.
495	    if (status === "gameover") {
496	      if (!overlayEl.parentNode) boardWrapEl.appendChild(overlayEl);
497	    } else if (overlayEl.parentNode) {
498	      overlayEl.parentNode.removeChild(overlayEl);
499	    }
500	    renderNext();
501	    renderHold();
502	  }
503	
504	  // ---- Game control ----
505	  function validTypes(queue) {
506	    if (!Array.isArray(queue)) return [];
507	    return queue.filter(function (t) { return SHAPES.hasOwnProperty(t); });
508	  }
509	
510	  function newGame(queue) {
511	    board = emptyBoard();
512	    score = 0;
513	    level = 1;
514	    lines = 0;
515	    status = "running";
516	    current = null;
517	    held = null;
518	    holdUsed = false;
519	    bag = [];
520	    if (Array.isArray(queue)) {
521	      next = validTypes(queue);
522	      scripted = true;
523	    } else {
524	      next = [];
525	      scripted = false;
526	    }
527	    spawn();
528	    startTimer();
529	    render();
530	  }
531	
532	  function setQueue(queue) {
533	    next = validTypes(queue);
534	    scripted = true;
535	    render();
536	  }
537	
538	  function setBoard(rows) {
539	    var b = emptyBoard();
540	    for (var r = 0; r < ROWS; r++) {
541	      var line = (rows && rows[r]) || "";
542	      for (var c = 0; c < COLS; c++) {
543	        var ch = line.charAt(c);
544	        b[r][c] = SHAPES.hasOwnProperty(ch) ? ch : "";
545	      }
546	    }
547	    board = b;
548	    render();
549	  }
550	
551	  function getBoard() {
552	    return board.map(function (row) {
553	      return row.map(function (v) { return v || "."; }).join("");
554	    });
555	  }
556	
557	  function getState() {
558	    var cur = null;
559	    if (current) {
560	      var cells = shapeCells(current.matrix, current.row, current.col);
561	      cells.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
562	      cur = { type: current.type, cells: cells };
563	    }
564	    return {
565	      current: cur,
566	      next: next.slice(),
567	      score: score,
568	      level: level,
569	      lines: lines,
570	      dropInterval: dropInterval(),
571	      hold: held,
572	      status: status
573	    };
574	  }
575	
576	  function setLevel(n) {
577	    var value = Math.floor(Number(n));
578	    if (!(value >= 1)) return;
579	    setLevelValue(value);
580	    render();
581	  }
582	
583	  function tick(n) {
584	    var steps = n === undefined ? 1 : Math.max(0, Math.floor(Number(n)) || 0);
585	    for (var i = 0; i < steps; i++) gravityStep();
586	    render();
587	  }
588	
589	  window.__tetris = {
590	    newGame: newGame,
591	    setQueue: setQueue,
592	    setBoard: setBoard,
593	    tick: tick,
594	    setLevel: setLevel,
595	    input: function (action) { applyInput(action); render(); },
596	    getBoard: getBoard,
597	    getState: getState
598	  };
599	
600	  // ---- Keyboard ----
601	  var KEYS = {
602	    ArrowLeft: "left",
603	    ArrowRight: "right",
604	    ArrowDown: "softDrop",
605	    " ": "hardDrop",
606	    ArrowUp: "rotateCW",
607	    c: "hold",
608	    C: "hold",
609	    Shift: "hold"
610	  };
611	
612	  document.addEventListener("keydown", function (e) {
613	    var action = KEYS[e.key];
614	    if (!action || e.metaKey || e.ctrlKey || e.altKey) return;
615	    e.preventDefault();
616	    window.__tetris.input(action);
617	  });
618	
619	  document.getElementById("new-game").addEventListener("click", function (e) {
620	    e.currentTarget.blur();
621	    newGame();
622	  });
623	
624	  newGame();
625	})();
626	</script>
627	</body>
628	</html>

