  7	<style>
  8	  :root {
  9	    --cell: 28px;
 10	    --bg: #14161c;
 11	    --panel: #1e2129;
 12	    --line: #2a2e38;
 13	    --text: #e8eaf0;
 14	    --muted: #9aa0ad;
